<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>'Notifications','subtitle'=>'Request updates and operational alerts assigned to your account.']) ?><section class="panel"><div class="panel-head"><form method="get" class="toolbar"><input type="search" name="q" value="<?= esc((string)service('request')->getGet('q')) ?>" placeholder="Search notifications"><select name="read"><option value="">All notifications</option><option value="unread" <?= service('request')->getGet('read')==='unread'?'selected':'' ?>>Unread</option><option value="read" <?= service('request')->getGet('read')==='read'?'selected':'' ?>>Read</option></select><button class="btn" type="submit">Filter</button><?php if(service('request')->getGet('q')||service('request')->getGet('read')): ?><a class="btn ghost" href="<?= site_url('notifications') ?>">Clear</a><?php endif; ?></form><form method="post" action="<?= site_url('notifications/read-all') ?>" data-confirm="Mark all notifications for <?= esc((string)session()->get('display_name'),'attr') ?> as read?"><?= csrf_field() ?><button class="btn" type="submit">Mark all read</button></form></div><p class="result-count"><?= (int)$total ?> notification(s)</p><div class="notification-list"><?php foreach($notifications as $n): ?><article class="notification-row <?= $n['is_read']?'':'unread' ?>"><span class="activity-icon"><?= ui_icon('bell') ?></span><div><b><?= esc(status_label($n['type'])) ?></b><p><?= esc($n['message']) ?></p><small><?= esc(fmt_date($n['created_at'],true)) ?></small></div><?php if(!$n['is_read']): ?><form method="post" action="<?= site_url('notifications/'.$n['id'].'/read') ?>"><?= csrf_field() ?><button class="btn small" type="submit">Mark read</button></form><?php endif; ?></article><?php endforeach; ?><?php if(empty($notifications)): ?><div class="empty">No notifications match your filters.</div><?php endif; ?></div><?php if($pagerLinks): ?><div class="pager" aria-label="Notification pagination"><?= $pagerLinks ?></div><?php endif; ?></section><?= $this->endSection() ?>
